mapper.update:
UPDATE inv_transfer_order SET status=#{nextStatus},version=version+1,
        approver_user_id=COALESCE(#{approverUserId},approver_user_id),approved_at=COALESCE(#{approvedAt},approved_at),
        dispatched_at=COALESCE(#{dispatchedAt},dispatched_at),closed_at=COALESCE(#{closedAt},closed_at),updated_at=#{updatedAt}
        WHERE tenant_id=#{tenantId} AND transfer_id=#{transferId} AND status=#{expectedStatus} AND version=#{expectedVersion}

UPDATE inv_transfer_line SET
        dispatched_quantity=dispatched_quantity+#{dispatchedDelta},
        received_quantity=received_quantity+#{receivedDelta},
        difference_quantity=difference_quantity+#{differenceDelta},updated_at=#{updatedAt}
        WHERE tenant_id=#{tenantId} AND transfer_line_id=#{transferLineId}
        AND received_quantity+#{receivedDelta}+difference_quantity+#{differenceDelta}
            <= dispatched_quantity+#{dispatchedDelta}
        AND dispatched_quantity+#{dispatchedDelta} <= requested_quantity
